import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyThongBao = () => {
    const [tabActive, setTabActive] = useState('view');
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [notifications, setNotifications] = useState([
        {
            id: 1,
            title: "Bảo trì thang máy",
            body: "Thang máy block A sẽ được bảo trì vào lúc 9h sáng mai.",
            date: "22/04/2026",
            sender: "AD"
        }
    ]);

    // State cho việc xác nhận xóa
    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [notiToDelete, setNotiToDelete] = useState(null);

    const handleSendNotification = () => {
        if (!title.trim() || !content.trim()) return;
        const newNoti = {
            id: Date.now(),
            title: title,
            body: content,
            date: new Date().toLocaleDateString('vi-VN'),
            sender: "AD"
        };
        setNotifications([newNoti, ...notifications]);
        setTitle('');
        setContent('');
        setTabActive('view');
    };

    // Mở khung xác nhận xóa
    const openConfirm = (id) => {
        setNotiToDelete(id);
        setShowDeleteConfirm(true);
    };

    // Thực hiện xóa
    const confirmDelete = () => {
        setNotifications(notifications.filter(n => n.id !== notiToDelete));
        setShowDeleteConfirm(false);
        setNotiToDelete(null);
    };

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', position: 'relative'
        }} className="glass-card">

            {/* Modal xác nhận xóa */}
            {showDeleteConfirm && (
                <div style={{
                    position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
                    backgroundColor: 'rgba(0,0,0,0.6)', display: 'flex', 
                    alignItems: 'center', justifyContent: 'center', zIndex: 1000
                }}>
                    <div style={{
                        backgroundColor: '#fff', padding: '30px', borderRadius: '20px',
                        textAlign: 'center', width: '300px'
                    }}>
                        <p style={{ fontWeight: 'bold', marginBottom: '20px', color: '#333' }}>Xác nhận xóa thông báo này?</p>
                        <div style={{ display: 'flex', gap: '10px', justifyContent: 'center' }}>
                            <button 
                                onClick={confirmDelete}
                                style={{ padding: '10px 20px', borderRadius: '10px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', cursor: 'pointer' }}
                            >Xác nhận</button>
                            <button 
                                onClick={() => setShowDeleteConfirm(false)}
                                style={{ padding: '10px 20px', borderRadius: '10px', border: '1px solid #ddd', backgroundColor: '#fff', cursor: 'pointer' }}
                            >Hủy</button>
                        </div>
                    </div>
                </div>
            )}

            <div style={{ padding: '20px', display: 'flex', gap: '15px' }}>
                <button onClick={() => setTabActive('view')} style={{ padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', backgroundColor: tabActive === 'view' ? '#333' : 'rgba(255,255,255,0.6)', color: tabActive === 'view' ? '#fff' : '#333', cursor: 'pointer' }}>Khung thông báo</button>
                <button onClick={() => setTabActive('send')} style={{ padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', backgroundColor: tabActive === 'send' ? '#8b5e5e' : 'rgba(255,255,255,0.6)', color: tabActive === 'send' ? '#fff' : '#333', cursor: 'pointer' }}>Gửi thông báo</button>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', overflow: 'hidden' }}>
                {tabActive === 'view' ? (
                    <div style={{ height: '100%', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        {notifications.map(noti => (
                            <div key={noti.id} style={{
                                backgroundColor: 'rgba(255,255,255,0.9)', padding: '20px', 
                                borderRadius: '20px', position: 'relative'
                            }}>
                                {/* Dấu X xóa */}
                                <div 
                                    onClick={() => openConfirm(noti.id)}
                                    style={{
                                        position: 'absolute', top: '15px', right: '20px',
                                        cursor: 'pointer', color: '#999', fontSize: '18px', fontWeight: 'bold'
                                    }}
                                >✕</div>

                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px', marginRight: '20px' }}>
                                    <span style={{ fontWeight: 'bold', color: '#8b5e5e', fontSize: '16px' }}>{noti.title}</span>
                                    <span style={{ fontSize: '12px', color: '#666' }}>{noti.date}</span>
                                </div>
                                <p style={{ margin: 0, fontSize: '14px', color: '#333', lineHeight: '1.5' }}>{noti.body}</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    /* Phần Gửi thông báo giữ nguyên như cũ */
                    <div style={{ backgroundColor: 'rgba(255,255,255,0.15)', borderRadius: '25px', padding: '30px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
                        <input style={{ width: '100%', padding: '12px', borderRadius: '12px', border: 'none' }} placeholder="Tiêu đề..." value={title} onChange={(e) => setTitle(e.target.value)} />
                        <textarea style={{ width: '100%', height: '150px', padding: '15px', borderRadius: '12px', border: 'none' }} placeholder="Nội dung chi tiết..." value={content} onChange={(e) => setContent(e.target.value)} />
                        <button onClick={handleSendNotification} style={{ alignSelf: 'flex-end', padding: '12px 40px', borderRadius: '12px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}>Gửi ngay</button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default QuanLyThongBao;
